findings.codeql_raw_query:
/**
 * @name Tainted data flow to exec in six.py
 * @description Check if user-controlled data flows to exec() call in six.py
 * @kind path-problem
 * @problem.severity high
 * @id py/six-exec-dataflow
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SixExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for exec() calls specifically in six.py
    exists(CodeExecution ce |
      sink = ce.getCode() and
      sink.asExpr().getLocation().getFile().getBaseName() = "six.py"
    )
  }
}

module SixExecFlow = TaintTracking::Global<SixExecConfig>;
import SixExecFlow::PathGraph

from SixExecFlow::PathNode source, SixExecFlow::PathNode sink
where SixExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Tainted data flows to exec() call from $@.", source.getNode(), "user input"
